item.content:encoded:
.home .content-wrapper .entry-header.page-header, .content-wrapper header.woocommerce-products-header {
    border-bottom: 0px solid rgba(0, 0, 0, 0.1);
    margin-bottom: 0px;
}

body:not(.activity) .item-body-wrap {
    position: relative;
    background: #fff;
    padding: 15px;
    border-radius: 4px;
    box-shadow: 0 1.5px 3px 0 rgba(0, 0, 0, 0.16);
}
